  void showSplash(){base("splash");LinearLayout c=new LinearLayout(this);c.setOrientation(1);c.setGravity(Gravity.CENTER);full(c);ImageView avatar=new ImageView(this);avatar.setImageResource(com.minhquan.magicos.R.drawable.avatar);avatar.setScaleType(ImageView.ScaleType.CENTER_CROP);GradientDrawable frame=bg(0xFF0C1B25,100);avatar.setBackground(frame);avatar.setClipToOutline(true);LinearLayout.LayoutParams ip=new LinearLayout.LayoutParams(d(124),d(124));c.addView(avatar,ip);RotateAnimation spin=new RotateAnimation(0,360,Animation.RELATIVE_TO_SELF,.5f,Animation.RELATIVE_TO_SELF,.5f);spin.setDuration(2300);spin.setRepeatCount(Animation.INFINITE);spin.setInterpolator(new LinearInterpolator());avatar.startAnimation(spin);TextView title=txt("MINHQUAN",24,INK);pad(title,14,18);c.addView(title);c.addView(txt("Đang khởi động MAGICOS…",13,0xFFC8D9EA));handler.postDelayed(()->{if(page.equals("splash"))showKey();},2600);}
