  void header(String title){LinearLayout h=new LinearLayout(this);h.setGravity(Gravity.CENTER_VERTICAL);h.setPadding(d(16),d(8),d(16),d(8));TextView back=txt("‹",36,INK);h.addView(back,new LinearLayout.LayoutParams(d(45),d(54)));back.setOnClickListener(v->showHome());TextView t=txt(title,22,INK);h.addView(t,new LinearLayout.LayoutParams(0,d(54),1));h.addView(new View(this),new LinearLayout.LayoutParams(d(45),1));panel.addView(h);}
