  void status(){LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(d(20),d(12),d(20),0);TextView t=txt(new SimpleDateFormat("HH:mm",Locale.getDefault()).format(new Date()),14,INK);bar.addView(t);bar.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));bar.addView(txt("●  ▰▰  ◕",14,INK));FrameLayout.LayoutParams p=new FrameLayout.LayoutParams(-1,d(46),Gravity.TOP);root.addView(bar,p);TextView island=txt("●",13,INK);island.setBackground(bg(Color.BLACK,30));FrameLayout.LayoutParams ip=new FrameLayout.LayoutParams(d(108),d(29),Gravity.TOP|Gravity.CENTER_HORIZONTAL);ip.topMargin=d(9);root.addView(island,ip);}
  void showLock(){base("lock");status();LinearLayout c=new LinearLayout(this);c.setGravity(Gravity.CENTER);c.setOrientation(1);FrameLayout.LayoutParams cp=new FrameLayout.LayoutParams(-1,-2,Gravity.CENTER);root.addView(c,cp);c.addView(txt(new SimpleDateFormat("EEEE, dd MMMM",new Locale("vi","VN")).format(new Date()),19,INK));clock=txt(new SimpleDateFormat("HH:mm",Locale.getDefault()).format(new Date()),68,INK);c.addView(clock);TextView swipe=txt("Vuốt lên để mở khóa  ↑",17,INK);FrameLayout.LayoutParams sp=new FrameLayout.LayoutParams(-1,d(80),Gravity.BOTTOM);root.addView(swipe,sp);swipe.setOnClickListener(v->showHome());root.setOnTouchListener((v,e)->{if(e.getAction()==0){downY=e.getY();return true;}if(e.getAction()==1){if(downY-e.getY()>d(65))showHome();return true;}return true;});}
  void showHome(){unlocked=true;base("home");status();LinearLayout screen=new LinearLayout(this);screen.setOrientation(1);FrameLayout.LayoutParams sp=new FrameLayout.LayoutParams(-1,-1);sp.topMargin=d(65);root.addView(screen,sp);TextView heading=txt("MAGICOS",30,INK);heading.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);heading.setPadding(d(24),d(20),0,d(12));screen.addView(heading);TextView subtitle=txt("Hệ điều hành mô phỏng · Native",13,0xFFC6D7EA);subtitle.setGravity(Gravity.LEFT);subtitle.setPadding(d(24),0,0,d(24));screen.addView(subtitle);ScrollView scroll=new ScrollView(this);screen.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout rows=new LinearLayout(this);rows.setOrientation(1);scroll.addView(rows);String[][] apps={{"⚽","Penalty"},{"✦","MAGICAI"},{"▣","MagicBank"},{"▤","Cửa Hàng"},{"☎","Điện thoại"},{"⚙","Cài đặt"},{"▦","Máy tính"},{"✎","Ghi chú"}};for(int i=0;i<apps.length;i+=4){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER);rows.addView(row);for(int j=i;j<Math.min(i+4,apps.length);j++){String label=apps[j][1];LinearLayout item=new LinearLayout(this);item.setOrientation(1);item.setGravity(Gravity.CENTER);LinearLayout.LayoutParams it=new LinearLayout.LayoutParams(0,d(115),1);row.addView(item,it);TextView icon=txt(apps[j][0],31,INK);icon.setBackground(bg(new int[]{0xFF187F6B,0xFF364E92,0xFF227E9C,0xFF9A633A}[j%4],19));item.addView(icon,new LinearLayout.LayoutParams(d(64),d(64)));TextView name=txt(label,11,INK);pad(name,0,8);item.addView(name);item.setOnClickListener(v->openApp(label));}}TextView dock=button("⌂  MAGICOS       ◉  Trung tâm điều khiển",0xAA15243A,INK);LinearLayout.LayoutParams dp=new LinearLayout.LayoutParams(-1,d(65));dp.setMargins(d(14),0,d(14),d(22));screen.addView(dock,dp);dock.setOnClickListener(v->showControl());root.setOnTouchListener((v,e)->{if(e.getAction()==0){downY=e.getY();return true;}if(e.getAction()==1){if(e.getY()-downY>d(90))showControl();return true;}return true;});}
