  void notes(){appBase("Ghi chú");EditText ed=new EditText(this);ed.setTextColor(INK);ed.setHintTextColor(0xFFB6C5D5);ed.setHint("Viết ghi chú...");ed.setGravity(Gravity.TOP);ed.setMinLines(10);ed.setBackground(bg(GLASS,16));pad(ed,16,14);ed.setText(getPreferences(0).getString("notes",""));panel.addView(ed,new LinearLayout.LayoutParams(-1,d(330)));TextView save=button("Lưu ghi chú",GREEN,0xFF08231C);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,d(55));lp.topMargin=d(14);panel.addView(save,lp);save.setOnClickListener(v->{getPreferences(0).edit().putString("notes",ed.getText().toString()).apply();Toast.makeText(this,"Đã lưu",Toast.LENGTH_SHORT).show();});}
  void calc(){appBase("Máy tính");TextView display=txt("0",36,INK);display.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);panel.addView(display,new LinearLayout.LayoutParams(-1,d(105)));final String[] val={""};String[] keys={"7","8","9","÷","4","5","6","×","1","2","3","−","C","0","=","+"};for(int i=0;i<4;i++){LinearLayout row=new LinearLayout(this);panel.addView(row);for(int j=0;j<4;j++){String k=keys[i*4+j];TextView b=button(k,0xFF2D4763,INK);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(0,d(70),1);bp.setMargins(d(3),d(3),d(3),d(3));row.addView(b,bp);b.setOnClickListener(v->{if(k.equals("C")){val[0]="";}else if(k.equals("=")){try{String expr=val[0].replace('×','*').replace('÷','/').replace('−','-');java.util.regex.Matcher m=java.util.regex.Pattern.compile("(-?\\d+(?:\\.\\d+)?)([+*/-])(-?\\d+(?:\\.\\d+)?)").matcher(expr);if(m.matches()){double a=Double.parseDouble(m.group(1)),z=Double.parseDouble(m.group(3));double result=m.group(2).equals("+")?a+z:m.group(2).equals("-")?a-z:m.group(2).equals("*")?a*z:a/z;val[0]=String.valueOf(result);}else val[0]="Lỗi";}catch(Exception ex){val[0]="Lỗi";}}else{if(val[0].equals("Lỗi"))val[0]="";val[0]+=k;}display.setText(val[0].isEmpty()?"0":val[0]);});}}}
